import { modalActive, modalClose, modal, buttons } from "./modules/modal";
import { register } from "./modules/register";
import { activeLink } from "./modules/SPA-Links";
import { headerLinks, footerLinks } from "./modules/register";
import { reloadPage, logoReload, footerReload } from "./modules/reload-page";
import { formDataCheck, loginActive, loginActiveMenu, loginActiveEvents, checkLogin } from "./modules/login";

window.addEventListener('DOMContentLoaded', () => {

    if (checkLogin) {
        loginActive();
        loginActiveMenu();
        loginActiveEvents();
    } else {

        modalActive(buttons, modal);
        modalClose(modal);

        reloadPage(footerReload, logoReload);

        const regHeader = document.querySelector('.reg__header');
        if (!regHeader) {
            activeLink(headerLinks, footerLinks);
        }

        // Регистрация

        const registerButton = document.querySelector('.link_header');
        register(registerButton);

        // Вход в аккаунт 

        formDataCheck();

    }

});

